// Deterministic message composition from document_types. No LLM here.
const body = $('Webhook').first().json.body || {};

const LABELS = {
  MEDICAL_CERTIFICATE: 'medical certificate',
  DISCHARGE_SUMMARY: 'discharge summary',
  HOSPITAL_BILL: 'hospital bill',
  PRESCRIPTION: 'prescription',
  DIAGNOSTIC_REPORT: 'diagnostic report',
  ID_PROOF: 'ID proof',
  POLICY_COPY: 'policy copy',
  CLAIM_FORM: 'signed claim form',
  FIR_COPY: 'FIR copy',
  DRIVING_LICENSE: 'driving licence',
  RC_COPY: 'vehicle registration certificate',
  REPAIR_ESTIMATE: 'repair estimate',
  REPAIR_INVOICE: 'repair invoice',
  SURVEY_REPORT: 'survey report',
  PHOTOS: 'damage photos',
  BANK_DETAILS: 'bank details',
  CANCELLED_CHEQUE: 'cancelled cheque'
};

function humanize(t) {
  const key = String(t || '').toUpperCase();
  return LABELS[key] || key.toLowerCase().replace(/_/g, ' ');
}

let types = Array.isArray(body.document_types) ? body.document_types : [];
if (types.length === 0 && body.document_type) types = [body.document_type];
if (types.length === 0 && Array.isArray(body.documents)) {
  types = body.documents.map(d => d.document_type).filter(Boolean);
}

const humanTypes = [...new Set(types.map(humanize))];
const claimRef = body.claim_number || body.external_claim_id || '';

let message;
if (body.message) {
  message = body.message;
} else if (humanTypes.length > 0) {
  message = `Please upload: ${humanTypes.join(', ')}` + (claimRef ? ` for claim ${claimRef}.` : '.');
} else {
  message = `There is an update on your claim${claimRef ? ' ' + claimRef : ''}. Please open COVE2E to continue.`;
}

return [{
  json: {
    channel: 'IN_APP',
    subject: claimRef ? `Action needed on claim ${claimRef}` : 'Action needed on your claim',
    message,
    document_types: types,
    journey_id: body.journey_id,
    claim_id: body.claim_id,
    action_id: body.action_id,
    composed_at: new Date().toISOString()
  }
}];

const body = $('Webhook').first().json.body || {};
const composed = $('Compose Notification').first().json;
const sent = $input.first().json || {};

const steps = [
  {
    key: 'compose',
    label: 'Composing notification',
    status: 'DONE',
    detail: composed.message
  },
  {
    key: 'send',
    label: 'Sending notification',
    status: 'DONE',
    detail: `Delivered via ${composed.channel} (${sent.delivery_status || 'QUEUED'})`
  }
];

return [{
  json: {
    ok: true,
    run_id: $execution.id,
    workflow: 'COVE2E Notification',
    action_id: body.action_id,
    journey_id: body.journey_id,
    claim_id: body.claim_id,
    steps,
    message: composed.message,
    subject: composed.subject,
    channel: composed.channel,
    document_types: composed.document_types,
    snapshot: null
  }
}];
